{
  "id": "app-mvxx1liq",
  "name": "Shopping list",
  "description": "A shopping list that reads my pantry inventory and adds anything I have fewer than 2 of. I can also add my own items, check them off in the store, and clear the checked ones.",
  "theme": {
    "accent": "#16a34a"
  },
  "read": [
    "pantry"
  ],
  "data": {
    "shopping": {
      "type": "list",
      "default": [],
      "fields": {
        "id": {
          "type": "string"
        },
        "name": {
          "type": "string"
        },
        "done": {
          "type": "boolean"
        }
      }
    }
  },
  "state": {
    "newItem": ""
  },
  "scripts": {
    "sync": {
      "code": "exports.mergeLow = ({low, existing}) => {\n  const out = [...(existing || [])];\n  const have = new Set(out.map(e => String(e.name || '').toLowerCase().trim()));\n  (low || []).forEach(name => {\n    if (!name) return;\n    const k = String(name).toLowerCase().trim();\n    if (!k || have.has(k)) return;\n    have.add(k);\n    out.push({id: Math.random().toString(36).slice(2) + Date.now().toString(36), name: String(name), done: false});\n  });\n  return out;\n};",
      "exports": [
        "mergeLow"
      ],
      "elements": []
    }
  },
  "screens": {
    "main": {
      "title": "Shopping list",
      "scroll": true,
      "body": {
        "type": "column",
        "style": {
          "padding": 16,
          "gap": 12
        },
        "children": [
          {
            "type": "card",
            "style": {
              "padding": 12
            },
            "children": [
              {
                "type": "text",
                "variant": "headline",
                "value": "Pantry low"
              },
              {
                "type": "text",
                "variant": "body",
                "style": {
                  "color": "muted"
                },
                "value": "{{plural(count(filter((shared.pantry ?? []), p => (p.count ?? 99) < 2)), 'item')}} with fewer than 2"
              },
              {
                "type": "button",
                "label": "Add low pantry items",
                "variant": "primary",
                "onTap": {
                  "run": "sync.mergeLow",
                  "args": {
                    "low": "map(filter((shared.pantry ?? []), p => (p.count ?? 99) < 2), p => p.name)",
                    "existing": "shopping"
                  },
                  "then": {
                    "set": "shopping",
                    "to": "value"
                  }
                }
              }
            ]
          },
          {
            "type": "row",
            "style": {
              "gap": 8,
              "align": "center"
            },
            "children": [
              {
                "type": "textfield",
                "placeholder": "Add item…",
                "bind": "newItem",
                "style": {
                  "grow": 1
                },
                "onSubmit": {
                  "if": "trim(newItem) != ''",
                  "then": [
                    {
                      "push": "shopping",
                      "value": {
                        "id": "uid()",
                        "name": "trim(newItem)",
                        "done": "false"
                      }
                    },
                    {
                      "set": "newItem",
                      "to": "''"
                    }
                  ]
                }
              },
              {
                "type": "button",
                "label": "Add",
                "variant": "primary",
                "onTap": {
                  "if": "trim(newItem) != ''",
                  "then": [
                    {
                      "push": "shopping",
                      "value": {
                        "id": "uid()",
                        "name": "trim(newItem)",
                        "done": "false"
                      }
                    },
                    {
                      "set": "newItem",
                      "to": "''"
                    }
                  ]
                }
              }
            ]
          },
          {
            "type": "column",
            "if": "len(shopping) > 0",
            "style": {
              "gap": 6
            },
            "children": [
              {
                "type": "text",
                "variant": "caption",
                "style": {
                  "color": "muted"
                },
                "value": "{{count(filter(shopping, s => s.done))}} of {{len(shopping)}} done"
              },
              {
                "type": "progress",
                "value": "{{len(shopping) == 0 ? 0 : count(filter(shopping, s => s.done)) / len(shopping)}}"
              }
            ]
          },
          {
            "type": "list",
            "items": "shopping",
            "as": "item",
            "reorder": true,
            "swipe": [
              {
                "label": "Delete",
                "do": {
                  "remove": "item"
                }
              }
            ],
            "empty": "No items — add one above or pull from pantry.",
            "row": {
              "type": "row",
              "style": {
                "align": "center",
                "gap": 10
              },
              "children": [
                {
                  "type": "check",
                  "bind": "item.done"
                },
                {
                  "type": "text",
                  "value": "{{item.name}}",
                  "style": {
                    "grow": 1,
                    "color": "{{item.done ? 'muted' : 'text'}}"
                  }
                }
              ]
            }
          },
          {
            "type": "button",
            "if": "count(filter(shopping, s => s.done)) > 0",
            "label": "{{'Clear checked (' + count(filter(shopping, s => s.done)) + ')'}}",
            "variant": "secondary",
            "onTap": {
              "remove": "shopping",
              "where": "item.done"
            }
          },
          {
            "type": "divider"
          },
          {
            "type": "text",
            "variant": "headline",
            "value": "Low in pantry (< 2)"
          },
          {
            "type": "list",
            "items": "sort(filter((shared.pantry ?? []), p => (p.count ?? 99) < 2), p => p.name)",
            "as": "p",
            "empty": "Pantry looks good — nothing under 2.",
            "row": {
              "type": "row",
              "style": {
                "align": "center",
                "gap": 10
              },
              "children": [
                {
                  "type": "column",
                  "style": {
                    "grow": 1
                  },
                  "children": [
                    {
                      "type": "text",
                      "value": "{{p.name}}"
                    },
                    {
                      "type": "text",
                      "variant": "caption",
                      "style": {
                        "color": "muted"
                      },
                      "value": "{{'Only ' + str(p.count ?? 0) + ' left'}}"
                    }
                  ]
                },
                {
                  "type": "button",
                  "if": "count(filter(shopping, s => lower(s.name) == lower(p.name))) == 0",
                  "label": "Add",
                  "variant": "secondary",
                  "onTap": {
                    "push": "shopping",
                    "value": {
                      "id": "uid()",
                      "name": "p.name",
                      "done": "false"
                    }
                  }
                },
                {
                  "type": "text",
                  "if": "count(filter(shopping, s => lower(s.name) == lower(p.name))) > 0",
                  "variant": "caption",
                  "style": {
                    "color": "muted"
                  },
                  "value": "✓ in list"
                }
              ]
            }
          },
          {
            "type": "text",
            "variant": "caption",
            "style": {
              "color": "muted"
            },
            "value": "Reads Pantry inventory."
          }
        ]
      }
    }
  },
  "start": "main"
}
